#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RunPolicy {
    Auto,
    Safe,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Reasoning {
    Off,
    Low,
    Deep,
}
pub fn reasoning(mode: &str, phase: &str) -> Reasoning {
    // The selected Agent mode is an upstream contract, not merely a UI label.
    // llama.cpp's Qwen template understands `low` and `xhigh`; preserving it
    // across tool, note, compaction and final turns avoids silently degrading
    // a Deep run after its first request.
    let _ = phase;
    if mode == "deep" {
        Reasoning::Deep
    } else {
        Reasoning::Low
    }
}
pub fn requires_approval(policy: RunPolicy, tool: &str, arguments: &serde_json::Value) -> bool {
    if tool == "run_terminal" && terminal_requires_explicit_approval(arguments) {
        return true;
    }
    policy == RunPolicy::Safe && (tool == "delete_file" || tool == "run_terminal")
}

/// Model-issued commands which can end or reconfigure the desktop/user/system
/// session never run silently, including in AUTO. This is deliberately parsed
/// as command words rather than matched as a free-form substring. The runner's
/// own `kill -TERM -<known child pgid>` bypasses this policy entirely: it is
/// internal cancellation machinery, not a model shell command.
pub fn terminal_requires_explicit_approval(arguments: &serde_json::Value) -> bool {
    let Some(command) = arguments.get("command").and_then(serde_json::Value::as_str) else {
        return true;
    };
    let command = command.trim();
    if command.is_empty() {
        return true;
    }
    // Compound shell forms obscure which program ultimately receives control.
    if command.contains('\n')
        || [";", "&&", "||", "`", "$(", "<", ">", "&"]
            .iter()
            .any(|part| command.contains(part))
    {
        return true;
    }
    command.split('|').any(stage_requires_explicit_approval)
}

fn stage_requires_explicit_approval(stage: &str) -> bool {
    let words = shell_words(stage);
    let Some((program, args)) = words.split_first() else {
        return true;
    };
    let program = program.rsplit('/').next().unwrap_or(program);
    // Shell interpreters and process wrappers can conceal a lifecycle command
    // in their child program/script. AUTO only permits directly classifiable
    // project commands; these forms need an explicit decision.
    if matches!(
        program,
        "sh" | "bash"
            | "dash"
            | "zsh"
            | "fish"
            | "sudo"
            | "doas"
            | "nohup"
            | "setsid"
            | "xargs"
            | "env"
            | "timeout"
            | "nice"
            | "ionice"
            | "exec"
            | "eval"
            | "source"
            | "."
    ) {
        return true;
    }
    if program == "command" {
        return wrapped_command_requires_approval(args);
    }
    match program {
        "loginctl" => args.iter().any(|arg| {
            matches!(
                arg.as_str(),
                "terminate-session"
                    | "terminate-user"
                    | "kill-session"
                    | "kill-user"
                    | "activate"
                    | "lock-session"
            )
        }),
        "systemctl" => args.iter().any(|arg| {
            matches!(
                arg.as_str(),
                "exit"
                    | "poweroff"
                    | "reboot"
                    | "halt"
                    | "suspend"
                    | "hibernate"
                    | "isolate"
                    | "stop"
                    | "restart"
                    | "kill"
            )
        }),
        "gnome-session-quit" | "shutdown" | "reboot" | "poweroff" | "halt" => true,
        // A model cannot prove that a numeric/name target belongs to its own
        // transient shell tree. Require approval; the runtime's own child-PGID
        // cancellation path remains automatic and is not represented here.
        "kill" | "pkill" | "killall" => true,
        "dbus-send" | "gdbus" => args.iter().any(|arg| {
            let lower = arg.to_ascii_lowercase();
            lower.contains("session")
                || lower.contains("logout")
                || lower.contains("power")
                || lower.contains("reboot")
                || lower.contains("org.gnome.shell")
                || lower.contains("login1")
        }),
        _ => false,
    }
}

fn wrapped_command_requires_approval(args: &[String]) -> bool {
    let Some(index) = args
        .iter()
        .position(|word| !word.starts_with('-') && !word.contains('='))
    else {
        return true;
    };
    stage_requires_explicit_approval(&args[index..].join(" "))
}

fn shell_words(stage: &str) -> Vec<String> {
    // The policy only needs a conservative lexical view. Any unbalanced quote
    // leaves a token that cannot equal a safe session command and the compound
    // command gate above already requests approval for shell syntax.
    stage
        .split_whitespace()
        .map(|word| word.trim_matches(['\'', '"']))
        .map(str::to_owned)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn session_commands_need_approval_even_in_auto() {
        for command in ["loginctl terminate-session 9", "loginctl --no-ask-password terminate-user yaroslav", "systemctl --user exit", "systemctl --user --no-block reboot", "gnome-session-quit --logout", "shutdown now", "pkill gnome-shell", "gdbus call --session --dest org.gnome.SessionManager --method org.gnome.SessionManager.Logout 0", "bash -c 'gnome-session-quit --logout'", "sudo reboot", "env FOO=1 gnome-session-quit --logout", "timeout 10 reboot", "exec reboot", "eval 'reboot'"] {
            assert!(terminal_requires_explicit_approval(&json!({"command":command})), "{command}");
        }
        assert!(!terminal_requires_explicit_approval(
            &json!({"command":"npm run build"})
        ));
        assert!(requires_approval(
            RunPolicy::Auto,
            "run_terminal",
            &json!({"command":"reboot"})
        ));
    }

    #[test]
    fn selected_reasoning_mode_survives_every_agent_phase() {
        for phase in [
            "plan",
            "investigate",
            "execute",
            "verify",
            "final",
            "final_continuation",
        ] {
            assert_eq!(reasoning("fast", phase), Reasoning::Low, "{phase}");
            assert_eq!(reasoning("deep", phase), Reasoning::Deep, "{phase}");
        }
    }

    #[test]
    fn investigation_keeps_reasoning_enabled_after_the_first_turn() {
        assert_eq!(reasoning("fast", "investigate"), Reasoning::Low);
        assert_eq!(reasoning("deep", "investigate"), Reasoning::Deep);
        assert_eq!(reasoning("fast", "execute"), Reasoning::Low);
        assert_eq!(reasoning("deep", "execute"), Reasoning::Deep);
        assert_eq!(reasoning("deep", "verify"), Reasoning::Deep);
    }
}

use super::todo::TaskPlan;
use std::collections::BTreeMap;

/// A compact, runtime-owned record of evidence gathered during this run. It is
/// not a second transcript: canonical tool turns remain the source of truth.
/// This working state is projected through compaction so an investigation does
/// not start over merely because old raw file output left the request.
#[derive(Clone, Debug, Default)]
pub struct InvestigatedItem {
    pub kind: String,
    pub path: String,
    pub finding: String,
    pub reads: usize,
    pub truncated: bool,
    /// Concise, model-authored facts retained independently of raw tool text.
    /// Raw excerpts are only a partial fallback and never make evidence complete.
    pub facts: Vec<String>,
    pub relevance: Vec<String>,
    pub unresolved: Vec<String>,
    /// `true` means a Notes checkpoint established sufficient task-specific
    /// facts. A successful physical read alone is intentionally only partial.
    pub evidence_complete: bool,
}

#[derive(Default)]
pub struct AgentState {
    pub notes: String,
    pub plan: TaskPlan,
    pub cancelled: bool,
    pub investigated: BTreeMap<String, InvestigatedItem>,
    pub consecutive_repeated_exploration: usize,
    pub synthesis_nudged: bool,
    pub saturation_round: usize,
    /// Evidence revisions are deliberately separate from the transcript. They
    /// let the loop request a concise, model-authored Task Notes checkpoint at
    /// useful boundaries without persisting private reasoning.
    pub evidence_revision: usize,
    pub noted_evidence_revision: usize,
    pub plan_checkpoint_evidence_revision: usize,
    pub post_saturation_retrievals: usize,
    pub resolved_missing_facts: Vec<String>,
}

impl AgentState {
    pub fn record_investigation(
        &mut self,
        kind: &str,
        path: String,
        finding: String,
        truncated: bool,
    ) -> bool {
        let key = format!("{kind}:{path}");
        let entry = self
            .investigated
            .entry(key)
            .or_insert_with(|| InvestigatedItem {
                kind: kind.to_owned(),
                path,
                finding: finding.clone(),
                reads: 0,
                truncated,
                facts: Vec::new(),
                relevance: Vec::new(),
                unresolved: Vec::new(),
                evidence_complete: false,
            });
        entry.reads += 1;
        let changed = entry.finding != finding || entry.truncated != truncated;
        if changed {
            entry.finding = finding;
            entry.truncated = truncated;
        }
        if entry.reads == 1 || changed {
            self.evidence_revision += 1;
            self.consecutive_repeated_exploration = 0;
            true
        } else {
            self.consecutive_repeated_exploration += 1;
            false
        }
    }

    pub fn investigated_summary(&self) -> Vec<String> {
        self.investigated
            .values()
            .map(|item| {
                format!("SOURCE: {}\nstatus: {}\nphysical_reads: {}\nfacts: {}\nrelevance: {}\nunresolved: {}\npartial_excerpt: {}",
                    item.path,
                    if item.evidence_complete { "complete_for_task" } else { "partial" },
                    item.reads,
                    if item.facts.is_empty() { "(no model-authored facts checkpointed yet)".into() } else { item.facts.join(" | ") },
                    if item.relevance.is_empty() { "(not classified)".into() } else { item.relevance.join(" | ") },
                    if item.unresolved.is_empty() { "none".into() } else { item.unresolved.join(" | ") },
                    item.finding)
            })
            .collect()
    }

    /// A projection budget, not data loss: canonical investigated evidence is
    /// retained in runtime state. Context handoffs need representative facts,
    /// not an unbounded copy of every file excerpt.
    pub fn investigated_summary_bounded(&self, max_items: usize, max_chars: usize) -> Vec<String> {
        self.investigated_summary()
            .into_iter()
            .take(max_items)
            .map(|entry| {
                let clipped = entry.chars().take(max_chars).collect::<String>();
                if entry.chars().count() > max_chars {
                    format!("{clipped} …")
                } else {
                    clipped
                }
            })
            .collect()
    }

    pub fn prior_investigation(&self, kind: &str, path: &str) -> Option<&InvestigatedItem> {
        self.investigated.get(&format!("{kind}:{path}"))
    }

    pub fn notes_checkpoint_due(&self) -> bool {
        self.evidence_revision > self.noted_evidence_revision
    }

    pub fn uncheckpointed_evidence_count(&self) -> usize {
        self.evidence_revision
            .saturating_sub(self.noted_evidence_revision)
    }

    pub fn checkpoint_notes(&mut self) {
        self.noted_evidence_revision = self.evidence_revision;
    }

    /// Promote only evidence explicitly checkpointed by the model. This avoids
    /// the old contradiction: `evidence_complete=true` paired with a shallow
    /// first-source excerpt that cannot support the current audit.
    pub fn checkpoint_source_evidence(&mut self, evidence: &serde_json::Value) {
        let Some(items) = evidence.as_array() else {
            return;
        };
        for item in items {
            let Some(path) = item.get("path").and_then(serde_json::Value::as_str) else {
                continue;
            };
            let facts = item
                .get("facts")
                .and_then(serde_json::Value::as_array)
                .map(|xs| {
                    xs.iter()
                        .filter_map(serde_json::Value::as_str)
                        .map(str::to_owned)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            if facts.is_empty() {
                continue;
            }
            for investigated in self
                .investigated
                .values_mut()
                .filter(|known| known.path == path)
            {
                investigated.facts = facts.clone();
                investigated.relevance = item
                    .get("relevance")
                    .and_then(serde_json::Value::as_array)
                    .map(|xs| {
                        xs.iter()
                            .filter_map(serde_json::Value::as_str)
                            .map(str::to_owned)
                            .collect()
                    })
                    .unwrap_or_default();
                investigated.unresolved = item
                    .get("unresolved")
                    .and_then(serde_json::Value::as_array)
                    .map(|xs| {
                        xs.iter()
                            .filter_map(serde_json::Value::as_str)
                            .map(str::to_owned)
                            .collect()
                    })
                    .unwrap_or_default();
                investigated.evidence_complete = item
                    .get("complete_for_task")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false)
                    && investigated.unresolved.is_empty();
            }
        }
    }

    pub fn mark_plan_checkpoint(&mut self) {
        self.plan_checkpoint_evidence_revision = self.evidence_revision;
    }

    pub fn plan_checkpoint_due(&self) -> bool {
        self.plan.has_open()
            && self
                .evidence_revision
                .saturating_sub(self.plan_checkpoint_evidence_revision)
                >= 3
    }

    /// Notes are a bounded snapshot of durable evidence, not an overwrite of
    /// everything the model learned earlier. Preserve distinct factual lines
    /// while allowing the model to supersede a repeated snapshot.
    pub fn merge_notes(&mut self, update: &str) -> bool {
        let mut lines = Vec::new();
        for text in [self.notes.as_str(), update] {
            for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
                if !lines
                    .iter()
                    .any(|known: &String| known.eq_ignore_ascii_case(line))
                {
                    lines.push(line.to_owned());
                }
            }
        }
        let merged = lines.join("\n");
        let bounded = if merged.chars().count() > 6_000 {
            merged.chars().take(6_000).collect::<String>()
        } else {
            merged
        };
        let changed = bounded != self.notes;
        self.notes = bounded;
        changed
    }

    pub fn invalidate_path(&mut self, path: &str) {
        self.investigated.retain(|_, item| item.path != path);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn notes_merge_retains_prior_distinct_facts_and_deduplicates_snapshots() {
        let mut state = AgentState::default();
        assert!(state.merge_notes("App.tsx: router shell\nBusiness: paid acquisition"));
        assert!(state.merge_notes("Business: paid acquisition\nmain.tsx: provider bootstrap"));
        assert!(state.notes.contains("App.tsx"));
        assert!(state.notes.contains("main.tsx"));
        assert!(!state.merge_notes("Business: paid acquisition"));
    }
}

//! Local V2 adaptation of Jan's ordered `TodoList`; the GUI calls it Task Plan.
use serde::{Deserialize, Serialize};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Status {
    Pending,
    InProgress,
    Completed,
    Abandoned,
}
impl Default for Status {
    fn default() -> Self {
        Self::Pending
    }
}
impl Status {
    fn open(self) -> bool {
        matches!(self, Self::Pending | Self::InProgress)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Item {
    pub content: String,
    #[serde(default)]
    pub status: Status,
}
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Phase {
    pub name: String,
    pub tasks: Vec<Item>,
}
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct TaskPlan {
    pub phases: Vec<Phase>,
}

impl TaskPlan {
    pub fn has_open(&self) -> bool {
        self.items().any(|task| task.status.open())
    }
    pub fn progress(&self) -> (usize, usize) {
        let tasks: Vec<_> = self.items().collect();
        (
            tasks
                .iter()
                .filter(|task| matches!(task.status, Status::Completed | Status::Abandoned))
                .count(),
            tasks.len(),
        )
    }
    pub fn active_phase(&self) -> Option<&str> {
        self.phases
            .iter()
            .find(|phase| {
                phase
                    .tasks
                    .iter()
                    .any(|item| item.status == Status::InProgress)
            })
            .map(|phase| phase.name.as_str())
    }
    pub fn open_summary(&self) -> Option<String> {
        let entries: Vec<_> = self
            .phases
            .iter()
            .flat_map(|phase| {
                phase
                    .tasks
                    .iter()
                    .filter_map(move |task| match task.status {
                        Status::Pending => Some(format!("• [{}] {}", phase.name, task.content)),
                        Status::InProgress => Some(format!("→ [{}] {}", phase.name, task.content)),
                        _ => None,
                    })
            })
            .collect();
        (!entries.is_empty()).then(|| entries.join("\n"))
    }
    pub fn init(&mut self, mut phases: Vec<Phase>) -> Result<(), String> {
        // A plan may be refined as investigation uncovers scope. Preserve the
        // terminal state of unchanged task labels so refinement never makes
        // evidence look unexplored again. New labels remain model-authored
        // pending work and ordering is still normalized below.
        let previous = self
            .items()
            .map(|item| (item.content.clone(), item.status))
            .collect::<std::collections::HashMap<_, _>>();
        let mut phase_names = std::collections::HashSet::new();
        let mut task_names = std::collections::HashSet::new();
        for phase in &mut phases {
            if phase.name.trim().is_empty() || !phase_names.insert(phase.name.clone()) {
                return Err("Task Plan phases must have unique names".into());
            }
            for task in &mut phase.tasks {
                if task.content.trim().is_empty() || !task_names.insert(task.content.clone()) {
                    return Err("Task Plan tasks must be non-empty and unique".into());
                }
                task.status = previous
                    .get(&task.content)
                    .copied()
                    .unwrap_or(Status::Pending);
            }
        }
        self.phases = phases;
        self.promote_next();
        Ok(())
    }
    pub fn start(&mut self, task: &str) -> Result<(), String> {
        let target = self
            .index_of(task)
            .ok_or_else(|| format!("unknown Task Plan item: {task}"))?;
        for (index, prior) in self.items().enumerate() {
            if index >= target {
                break;
            }
            if prior.status.open() {
                return Err("cannot start work before earlier Task Plan items are closed".into());
            }
        }
        for item in self.items_mut() {
            if item.status == Status::InProgress {
                item.status = Status::Pending;
            }
        }
        self.item_mut(target).expect("known item").status = Status::InProgress;
        Ok(())
    }
    pub fn finish(&mut self, task: &str, abandoned: bool) -> Result<(), String> {
        let index = self
            .index_of(task)
            .ok_or_else(|| format!("unknown Task Plan item: {task}"))?;
        self.item_mut(index).expect("known item").status = if abandoned {
            Status::Abandoned
        } else {
            Status::Completed
        };
        self.promote_next();
        Ok(())
    }
    fn items(&self) -> impl Iterator<Item = &Item> {
        self.phases.iter().flat_map(|phase| phase.tasks.iter())
    }
    fn items_mut(&mut self) -> impl Iterator<Item = &mut Item> {
        self.phases
            .iter_mut()
            .flat_map(|phase| phase.tasks.iter_mut())
    }
    fn index_of(&self, task: &str) -> Option<usize> {
        self.items().position(|item| item.content == task)
    }
    fn item_mut(&mut self, mut index: usize) -> Option<&mut Item> {
        for phase in &mut self.phases {
            if index < phase.tasks.len() {
                return phase.tasks.get_mut(index);
            }
            index -= phase.tasks.len();
        }
        None
    }
    fn promote_next(&mut self) {
        if self.items().any(|item| item.status == Status::InProgress) {
            return;
        }
        if let Some(item) = self.items_mut().find(|item| item.status == Status::Pending) {
            item.status = Status::InProgress;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn phase(name: &str, tasks: &[&str]) -> Phase {
        Phase {
            name: name.into(),
            tasks: tasks
                .iter()
                .map(|content| Item {
                    content: (*content).into(),
                    status: Status::Completed,
                })
                .collect(),
        }
    }
    #[test]
    fn orders_and_promotes_items() {
        let mut plan = TaskPlan::default();
        plan.init(vec![
            phase("Setup", &["scaffold"]),
            phase("Verify", &["test"]),
        ])
        .unwrap();
        assert_eq!(plan.active_phase(), Some("Setup"));
        assert!(plan.start("test").is_err());
        plan.finish("scaffold", false).unwrap();
        assert_eq!(plan.active_phase(), Some("Verify"));
        plan.finish("test", false).unwrap();
        assert!(!plan.has_open());
        assert_eq!(plan.progress(), (2, 2));
    }

    #[test]
    fn refinement_keeps_terminal_status_for_same_task() {
        let mut plan = TaskPlan::default();
        plan.init(vec![phase(
            "Setup",
            &["inspect structure", "identify flow"],
        )])
        .unwrap();
        plan.finish("inspect structure", false).unwrap();
        plan.init(vec![
            phase("Setup", &["inspect structure", "identify flow"]),
            phase("Synthesis", &["write audit"]),
        ])
        .unwrap();
        let setup = &plan.phases[0].tasks;
        assert_eq!(setup[0].status, Status::Completed);
        assert_eq!(setup[1].status, Status::InProgress);
    }
}

