/// Targeted retrievals that can follow saturation boundaries: a floor of 2
/// plus one for each open Task Plan item that still needs evidence, so an
/// unprocessed multi-item plan doesn't hit the closeout wall while a truly
/// closed plan still gets bounded.
pub fn saturated_retrieval_budget(&self) -> usize {
    let (completed, total) = self.plan.progress();
    2usize.saturating_add(total.saturating_sub(completed))
}
pub fn saturated_retrieval_exhausted(&self) -> bool {
    self.post_saturation_retrievals >= self.saturated_retrieval_budget()
}
pub fn fact_already_resolved(&self, reason: &str) -> bool {
    let reason = reason.trim();
    self
        .resolved_missing_facts
        .iter()
        .any(|known| known.trim().eq_ignore_ascii_case(reason) && !known.trim().is_empty())
}
