/// The saturation boundary is a signal of depth, not a semantic end
/// marker: while Task Plan items are still open, the reminder must
/// keep the remaining work visible and must not declare
/// exploration complete.
fn saturation_reminder(state: &AgentState, round: usize) -> String {
    let investigated = state.investigated.len();
    let open = state.plan.open_summary().unwrap_or_default();
    let remaining = state
        .saturated_retrieval_budget()
        .saturating_sub(state.post_saturation_retrievals);
    if state.plan.has_open() {
        if round == 1 {
            format!(
                "Coverage of the investigated area is probably sufficient (saturation round 1). {investigated} investigated sources have durable evidence and Task Notes contains current findings — but that does not complete an open Task Plan. Still open:\n{open}\nTargeted retrieval of a named missing fact for those open items is still allowed. Broad batches aren't. Before broader investigation, identify one precisely unresolved fact, or honestly close the current Task Plan work naming the gap."
            )
        } else {
            format!(
                "Second saturation boundary: broad exploration is now restricted. Task Plan still has open work:\n{open}\nFor each, either use one targeted `read_file` call with a `reason` naming one missing fact and a narrow line range, or close it in Task Notes with the named gap before finalization. Don't batch list directories, reconstruct whole files, use terminal alternatives, or ask. Targeted retrievals remaining: {remaining}."
            )
        }
    } else {
        if round == 1 {
            format!(
                "Coverage is probably sufficient for synthesis (saturation round 1). {investigated} investigated sources have durable evidence and Task Notes contains current findings. Before any broad investigation, identify one precisely unresolved fact. Otherwise, update/close the current Task Plan work and write the audit requested as final answer."
            )
        } else {
            format!(
                "Second saturation boundary: broad exploration is now restricted. If the evidence is insufficient, use one `read_file` call with a `reason` naming one missing fact and a narrow line range; then checkpoint that fact and synthesize. Don't batch list directories, reconstruct whole files, use terminal alternatives, or ask. Targeted retrievals used: {}.",
                state.post_saturation_retrievals
            )
        }
    }
}
