/// the plan's still-open work, so an unprocessed multi-item audit can still
/// gather needed evidence, while broad or repeated fact hunting is rejected.
/// Keep this as a pure predicate so the capability registry and the
/// execution defense don't diverge again.
fn rejects_saturated_tool(state: &AgentState, tool: &ValidatedCall) -> bool {
    if state.saturation_round < 2 {
        return false;
    }
    if matches!(tool.name.as_str(), "task_plan" | "task_notes") {
        return false;
    }
    if tool.name == "read_file" {
        let reason = tool
            .arguments
            .get("reason")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .trim();
        return reason.is_empty()
            || (tool.arguments.get("start_line").is_none()
                && tool.arguments.get("end_line").is_none())
            || state.saturated_retrieval_exhausted()
            || state.fact_already_resolved(reason);
    }
    true
}
