/// Saturation is a depth signal, not a semantic end marker. When Task Plan
/// items are still open, the boundary reminder must keep the remaining work
/// visible and must never declare exploration complete: the regression that
/// made the Deep run close items 4-11 by batch after hitting a heuristic
/// threshold came exactly from asserting synthesis there.
fn saturation_reminder(state: &AgentState, round: usize) -> String {
    let investigated = state.investigated.len();
    if state.plan.has_open() {
        let open = state.plan.open_summary().unwrap_or_default();
        if round == 1 {
            return format!(
                "Coverage of the investigated area is probably sufficient (saturation round 1). {investigated} investigated sources have durable evidence and Task Notes contains current findings — but that does not complete an open Task Plan. Still open:\n{open}\nTargeted retrieval of a named missing fact for those open items is still allowed. Broad batches aren't. Before broadening, identify one precisely unresolved fact, or honestly close the current Task Plan work naming the gap."
            );
        }
        let remaining = state
            .saturated_retrieval_budget()
            .saturating_sub(state.post_saturation_retrievals);
        return format!(
            "Second saturation boundary: broad exploration is now restricted. Task Plan still has open work:\n{open}\nFor each open item, either use one targeted `read_file` call with a `reason` naming one missing fact and a narrow line range, or close it in Task Notes with the named gap before finalization. Don't batch list directories, reconstruct whole files, use terminal alternatives, or ask. Targeted retrievals remaining: {remaining}."
        );
    }
    if round == 1 {
        format!(
            "Coverage is probably sufficient for synthesis (saturation round 1). {investigated} investigated sources have durable evidence and Task Notes contains current findings. Before any broad investigation, identify one precisely unresolved fact. Otherwise, update/close the current Task Plan work and write the audit requested as the final answer."
        )
    } else {
        format!(
            "Second saturation boundary: broad exploration is now restricted. If the evidence is insufficient, use one `read_file` call with a `reason` naming one missing fact and a narrow line range; then checkpoint that fact and synthesize. Don't batch list directories, reconstruct whole files, use terminal alternatives, or ask. Targeted retrievals used: {}.",
            state.post_saturation_retrievals
        )
    }
}

/// The synthesis checkpoint projects consolidation work. That's a true
/// end state only when Task Plan actually is closed.
fn synthesis_checkpoint_reminder(state: &AgentState) -> String {
    match state.plan.open_summary() {
        Some(open) => format!(
            "SYNTHESIS CHECKPOINT: broad coverage is established, but Task Plan still has open work:\n{open}\nFor those open items, keep collecting targeted evidence, or honestly close the plan first, naming the specific gap in Task Notes. Don't rediscover the project or pre-draft the final answer in this checkpoint."
        ),
        None => "SYNTHESIS CHECKPOINT: exploration is complete. Consolidate only new durable findings into Task Notes and honestly close the Task Plan. Don't rediscover the project or pre-draft the final answer in this checkpoint; present the audit in the next final phase."
            .to_owned(),
    }
}

/// The forced plan closeout / checkpoint turn must remain reachable even while
/// saturation has narrowed capability: closing the plan, recording an honest
/// gap in Task Notes, or one more targeted retrieval must all be real options.
/// A task_plan-only wall is exactly what caused the Deep audit to close
/// uninvestigated items by batch.
fn visible_tools_for(
    final_continuation_turn: bool,
    planning_turn: bool,
    notes_checkpoint_turn: bool,
    phase: &str,
    state: &AgentState,
) -> Value {
    if final_continuation_turn {
        json!([])
    } else if planning_turn {
        if state.saturation_round >= 2 {
            saturation_tools()
        } else {
            planning_tools()
        }
    } else if notes_checkpoint_turn {
        notes_tools()
    } else if phase == "final" {
        json!([])
    } else if state.saturation_round >= 2 {
        saturation_tools()
    } else {
        tools()
    }
}
```

