/// capability boundary, rather than another advisory paragraph the model can
/// ignore. The budget scales with the number of open items still lacking
/// `complete_for_task` evidence so a large audit is not starved at 2 reads.
pub fn post_saturation_read_budget(state: &AgentState) -> usize {
